Design note:
- Graph stored as ordered dict of (fn, deps_tuple); reverse adjacency built for in-degree tracking.
- Validation: linear scan for missing deps, iterative DFS (color array) for cycles — no recursion.
- Topological order: Kahn's algorithm with a min-heap keyed by insertion index.
- Run: single scheduler thread submits ready tasks to a `ThreadPoolExecutor`, consumes completions via `as_completed`, decrements in-degrees, propagates failures to transitive dependents. No per-completion full scans; adjacency lists give O(1) per-edge updates.

### solution.py

```python
"""Dependency-aware parallel task runner for build/asset pipelines."""

from __future__ import annotations

import threading
from collections import deque
from concurrent.futures import ThreadPoolExecutor, Future
from dataclasses import dataclass, field
from typing import Any, Callable, Iterable


class GraphError(Exception):
    pass


class MissingDependencyError(GraphError):
    def __init__(self, task: str, dependency: str) -> None:
        self.task = task
        self.dependency = dependency
        super().__init__(
            f"Task {task!r} depends on {dependency!r} which is not a registered task"
        )


class CycleError(GraphError):
    def __init__(self, cycle: list[str]) -> None:
        self.cycle = cycle
        cycle_str = " -> ".join(cycle)
        super().__init__(f"Dependency cycle detected: {cycle_str}")


@dataclass
class RunResult:
    results: dict[str, Any] = field(default_factory=dict)
    errors: dict[str, BaseException] = field(default_factory=dict)
    skipped: set[str] = field(default_factory=set)
    order: list[str] = field(default_factory=list)


class _Task:
    __slots__ = ("name", "fn", "deps", "index")

    def __init__(self, name: str, fn: Callable[..., Any], deps: tuple[str, ...], index: int):
        self.name = name
        self.fn = fn
        self.deps = deps
        self.index = index


class TaskGraph:
    def __init__(self) -> None:
        self._tasks: dict[str, _Task] = {}
        self._order: list[str] = []  # insertion order of names

    def add_task(self, name: str, fn: Callable[..., Any], deps: Iterable[str] = ()) -> None:
        if not isinstance(name, str):
            raise TypeError(f"Task name must be a str, got {type(name).__name__}")
        if not callable(fn):
            raise TypeError(f"Task fn must be callable, got {type(fn).__name__}")

        # Reject bare string for deps
        if isinstance(deps, str):
            raise TypeError(
                "deps must be an iterable of task names (list/tuple/set), not a bare str"
            )

        # Materialise deps
        deps_list = list(deps)
        for d in deps_list:
            if not isinstance(d, str):
                raise TypeError(f"Dependency must be a str, got {type(d).__name__}")

        # Duplicate deps
        seen: set[str] = set()
        for d in deps_list:
            if d in seen:
                raise ValueError(
                    f"Duplicate dependency {d!r} in task {name!r}"
                )
            seen.add(d)

        # Duplicate task name
        if name in self._tasks:
            raise ValueError(f"Task {name!r} is already registered")

        self._tasks[name] = _Task(name, fn, tuple(deps_list), len(self._order))
        self._order.append(name)

    # ------------------------------------------------------------------
    # Validation
    # ------------------------------------------------------------------

    def _validate(self) -> None:
        # 1. Missing dependencies (insertion order, deps in given order)
        for name in self._order:
            task = self._tasks[name]
            for d in task.deps:
                if d not in self._tasks:
                    raise MissingDependencyError(name, d)

        # 2. Cycle detection (iterative DFS)
        self._detect_cycle()

    def _detect_cycle(self) -> None:
        # Colors: 0=white, 1=gray, 2=black
        color: dict[str, int] = {n: 0 for n in self._order}
        # For cycle path reconstruction
        path: list[str] = []
        path_set: set[str] = set()

        for start in self._order:
            if color[start] != 0:
                continue
            # Iterative DFS using explicit stack
            # Stack entries: (node, dep_index)
            # dep_index tells which dep to process next
            stack: list[tuple[str, int]] = []

            color[start] = 1
            path.append(start)
            path_set.add(start)
            stack.append((start, 0))

            while stack:
                node, di = stack[-1]
                task = self._tasks[node]
                advanced = False

                while di < len(task.deps):
                    dep = task.deps[di]
                    di += 1
                    if color[dep] == 1:
                        # Found cycle: extract from first occurrence of dep in path
                        idx = path.index(dep)
                        cycle = path[idx:] + [dep]
                        raise CycleError(cycle)
                    if color[dep] == 0:
                        color[dep] = 1
                        path.append(dep)
                        path_set.add(dep)
                        stack[-1] = (node, di)
                        stack.append((dep, 0))
                        advanced = True
                        break

                if not advanced:
                    # All deps processed for this node
                    stack.pop()
                    color[node] = 2
                    path.pop()
                    path_set.discard(node)

    # ------------------------------------------------------------------
    # Topological order
    # ------------------------------------------------------------------

    def topological_order(self) -> list[str]:
        self._validate()
        return self._topo_sort()

    def _topo_sort(self) -> list[str]:
        import heapq

        n = len(self._tasks)
        if n == 0:
            return []

        # in_degree[name] = number of deps of name
        in_degree: dict[str, int] = {}
        # reverse adjacency: for each dep, list of tasks that depend on it
        dependents: dict[str, list[str]] = {name: [] for name in self._tasks}

        for name in self._order:
            task = self._tasks[name]
            in_degree[name] = len(task.deps)
            for d in task.deps:
                dependents[d].append(name)

        # Min-heap by insertion index
        heap: list[tuple[int, str]] = []
        for name in self._order:
            if in_degree[name] == 0:
                heapq.heappush(heap, (self._tasks[name].index, name))

        result: list[str] = []
        while heap:
            _, name = heapq.heappop(heap)
            result.append(name)
            for dep_name in dependents[name]:
                in_degree[dep_name] -= 1
                if in_degree[dep_name] == 0:
                    heapq.heappush(heap, (self._tasks[dep_name].index, dep_name))

        return result

    # ------------------------------------------------------------------
    # Run
    # ------------------------------------------------------------------

    def run(self, max_workers: int = 4, *, fail_fast: bool = False) -> RunResult:
        if not isinstance(max_workers, int) or max_workers < 1:
            raise ValueError(f"max_workers must be >= 1, got {max_workers}")

        self._validate()

        n = len(self._tasks)
        if n == 0:
            return RunResult()

        # Build in-degree and dependents maps
        in_degree: dict[str, int] = {}
        dependents: dict[str, list[str]] = {name: [] for name in self._tasks}

        for name in self._order:
            task = self._tasks[name]
            in_degree[name] = len(task.deps)
            for d in task.deps:
                dependents[d].append(name)

        # Ready queue: min-heap by insertion index
        import heapq
        ready: list[tuple[int, str]] = []
        for name in self._order:
            if in_degree[name] == 0:
                heapq.heappush(ready, (self._tasks[name].index, name))

        # Scheduling state
        running: dict[str, Future] = {}  # name -> future
        results: dict[str, Any] = {}
        errors: dict[str, BaseException] = {}
        skipped: set[str] = set()
        order: list[str] = []
        failure_recorded: bool = False
        completed: set[str] = set()  # names that have been scheduled (running/done)

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            # Submit initial ready tasks
            self._submit_ready(ready, executor, running, completed,
                               max_workers, failure_recorded, fail_fast)

            # Main scheduling loop
            while running:
                # Wait for any future to complete
                done, _ = _as_completed_any(running)

                name = done
                fut = running.pop(name)
                completed.add(name)

                try:
                    result = fut.result()
                    results[name] = result
                    order.append(name)

                    # Release dependents
                    for dep_name in dependents[name]:
                        in_degree[dep_name] -= 1
                        if in_degree[dep_name] == 0:
                            if not failure_recorded or not fail_fast:
                                heapq.heappush(ready, (self._tasks[dep_name].index, dep_name))

                except Exception as e:
                    errors[name] = e
                    order.append(name)
                    if fail_fast:
                        failure_recorded = True
                    # Mark transitive dependents as skipped
                    self._mark_skipped(name, dependents, skipped, in_degree, ready)

                # Submit newly ready tasks
                self._submit_ready(ready, executor, running, completed,
                                   max_workers, failure_recorded, fail_fast)

        # Any remaining tasks in ready that were never submitted (fail_fast)
        while ready:
            _, name = heapq.heappop(ready)
            if name not in completed:
                skipped.add(name)

        # Also mark any remaining unstarted tasks (tasks with in_degree > 0
        # that were never released due to upstream failures)
        for name in self._order:
            if name not in results and name not in errors and name not in skipped:
                skipped.add(name)

        return RunResult(
            results=results,
            errors=errors,
            skipped=skipped,
            order=order,
        )

    def _submit_ready(
        self,
        ready: list[tuple[int, str]],
        executor: ThreadPoolExecutor,
        running: dict[str, Future],
        completed: set[str],
        max_workers: int,
        failure_recorded: bool,
        fail_fast: bool,
    ) -> None:
        while ready and len(running) < max_workers:
            if fail_fast and failure_recorded:
                break
            idx, name = heapq.heappop(ready)
            if name in completed:
                continue
            task = self._tasks[name]
            dep_args: dict[str, Any] = {}
            for d in task.deps:
                dep_args[d] = self._results_snapshot[d]
            future = executor.submit(task.fn, **dep_args)
            running[name] = future
            self._results_snapshot[name] = None  # placeholder

    def _mark_skipped(
        self,
        failed_name: str,
        dependents: dict[str, list[str]],
        skipped: set[str],
        in_degree: dict[str, int],
        ready: list[tuple[int, str]],
    ) -> None:
        """BFS to mark all transitive dependents as skipped."""
        queue = deque()
        for dep_name in dependents[failed_name]:
            if dep_name not in skipped:
                skipped.add(dep_name)
                queue.append(dep_name)
        while queue:
            cur = queue.popleft()
            for dep_name in dependents[cur]:
                if dep_name not in skipped:
                    skipped.add(dep_name)
                    queue.append(dep_name)
        # Remove skipped from ready
        ready[:] = [(idx, nm) for idx, nm in ready if nm not in skipped]

    # Snapshot of results for dependency resolution (set after success)
    _results_snapshot: dict[str, Any]


def _as_completed_any(running: dict[str, Future]) -> tuple[str, Future]:
    """Block until any future in `running` completes. Return (name, future)."""
    from concurrent.futures import as_completed
    for fut in as_completed(running.values()):
        for name, f in running.items():
            if f is fut:
                return name, fut
    # Should not reach here
    raise RuntimeError("No running tasks")
