        for d in deps_list:
            if not isinstance(d, str):
                raise TypeError(f"Dependency must be a str, got {type(d).__name__}")
        seen: set[str] = set()
        for d in deps_list:
            if d in seen:
                raise ValueError(f"Duplicate dependency {d!r} in task {name!r}")
            seen.add(d)
        if name in self._tasks:
            raise ValueError(f"Task {name!r} is already registered")
        self._tasks[name] = _Task(name, fn, tuple(deps_list), len(self._order))
        self._order.append(name)

    # ------------------------------------------------------------------
    def _validate(self) -> None:
        for name in self._order:
            task = self._tasks[name]
            for d in task.deps:
                if d not in self._tasks:
                    raise MissingDependencyError(name, d)
        self._detect_cycle()

    def _detect_cycle(self) -> None:
        color: dict[str, int] = {n: 0 for n in self._order}
        path: list[str] = []

        for start in self._order:
            if color[start] != 0:
                continue
            color[start] = 1
            path.append(start)
            stack: list[tuple[str, int]] = [(start, 0)]

            while stack:
                node, di = stack[-1]
                task = self._tasks[node]
                advanced = False
                while di < len(task.deps):
                    dep = task.deps[di]
                    di += 1
                    if color[dep] == 1:
                        idx = path.index(dep)
                        cycle = path[idx:] + [dep]
                        raise CycleError(cycle)
                    if color[dep] == 0:
                        color[dep] = 1
                        path.append(dep)
                        stack[-1] = (node, di)
                        stack.append((dep, 0))
                        advanced = True
                        break
                if not advanced:
                    stack.pop()
                    color[node] = 2
                    path.pop()

    # ------------------------------------------------------------------
    def topological_order(self) -> list[str]:
        self._validate()
        return self._topo_sort()

    def _topo_sort(self) -> list[str]:
        if not self._tasks:
            return []
        in_degree: dict[str, int] = {}
        dependents: dict[str, list[str]] = {name: [] for name in self._tasks}
        for name in self._order:
            task = self._tasks[name]
            in_degree[name] = len(task.deps)
            for d in task.deps:
                dependents[d].append(name)

        heap: list[tuple[int, str]] = []
        for name in self._order:
            if in_degree[name] == 0:
                heapq.heappush(heap, (self._tasks[name].index, name))

        result: list[str] = []
        while heap:
            _, name = heapq.heappop(heap)
            result.append(name)
            for dep_name in dependents[name]:
                in_degree[dep_name] -= 1
                if in_degree[dep_name] == 0:
                    heapq.heappush(heap, (self._tasks[dep_name].index, dep_name))
        return result

    # ------------------------------------------------------------------
    def run(self, max_workers: int = 4, *, fail_fast: bool = False) -> RunResult:
        if not isinstance(max_workers, int) or max_workers < 1:
            raise ValueError(f"max_workers must be >= 1, got {max_workers}")
        self._validate()
        if not self._tasks:
            return RunResult()

        # Build in-degree / dependents
        in_degree: dict[str, int] = {}
        dependents: dict[str, list[str]] = {name: [] for name in self._tasks}
        for name in self._order:
            task = self._tasks[name]
            in_degree[name] = len(task.deps)
            for d in task.deps:
                dependents[d].append(name)

        ready: list[tuple[int, str]] = []
        for name in self._order:
            if in_degree[name] == 0:
                heapq.heappush(ready, (self._tasks[name].index, name))

        results: dict[str, Any] = {}
        errors: dict[str, BaseException] = {}
        skipped: set[str] = set()
        order: list[str] = []
        running: dict[str, Future] = {}
        failure_recorded = False
        scheduled: set[str] = set()

        # We use a threading approach: scheduler in main thread.
        # Executor with fixed pool.
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            def submit_ready() -> None:
                while ready and len(running) < max_workers:
                    if fail_fast and failure_recorded:
                        break
                    idx, name = heapq.heappop(ready)
                    if name in scheduled:
                        continue
                    if name in skipped:
                        continue
                    task = self._tasks[name]
                    kw: dict[str, Any] = {}
                    for d in task.deps:
                        kw[d] = results[d]
                    fut = executor.submit(task.fn, **kw)
                    running[name] = fut
                    scheduled.add(name)

            def mark_skipped(name: str) -> None:
                queue = deque(dependents[name])
                for dep_name in queue:
                    if dep_name not in skipped:
                        skipped.add(dep_name)
                        queue.append(dep_name)
                        in_degree[dep_name] = -1  # poison so it's never ready

            submit_ready()

            while running:
                fut = next(as_completed(running.values()))
                name = next(n for n, f in running.items() if f is fut)
                del running[name]

                try:
                    val = fut.result()
                    results[name] = val
                    order.append(name)
                    for dep_name in dependents[name]:
                        if in_degree[dep_name] > 0:
                            in_degree[dep_name] -= 1
                            if in_degree[dep_name] == 0 and dep_name not in skipped:
                                heapq.heappush(ready, (self._tasks[dep_name].index, dep_name))
                except Exception as e:
                    errors[name] = e
                    order.append(name)
                    if fail_fast:
                        failure_recorded = True
                    mark_skipped(name)

                submit_ready()

        # Remaining in ready that weren't submitted (fail_fast stop)
        for _, name in ready:
            if name not in scheduled and name not in skipped:
                skipped.add(name)
        # Anything not in results/errors/skipped
        for name in self._order:
            if name not in results and name not in errors and name not in skipped:
                skipped.add(name)

        return RunResult(results=results, errors=errors, skipped=skipped, order=order)
