```python
import pytest
import time
import threading
from solution import (
    TaskGraph,
    RunResult,
    GraphError,
    MissingDependencyError,
    CycleError,
)


# ---------- add_task basics ----------

def test_add_task_and_topo_order_simple():
    g = TaskGraph()
    g.add_task("a", lambda: 1)
    g.add_task("b", lambda **kw: kw["a"] + 1, deps=["a"])
    g.add_task("c", lambda **kw: kw["b"] + 1, deps=["b"])
    assert g.topological_order() == ["a", "b", "c"]


def test_topo_order_insertion_tiebreak():
    g = TaskGraph()
    g.add_task("c", lambda: 3)
    g.add_task("a", lambda **kw: kw["c"], deps=["c"])
    g.add_task("b", lambda: 2)
    assert g.topological_order() == ["c", "a", "b"]


def test_add_task_type_errors():
    g = TaskGraph()
    with pytest.raises(TypeError):
        g.add_task(123, lambda: 0)
    with pytest.raises(TypeError):
        g.add_task("x", 42)
    with pytest.raises(TypeError):
        g.add_task("x", lambda: 0, deps="fetch")  # bare str


def test_add_task_duplicate_name():
    g = TaskGraph()
    g.add_task("a", lambda: 1)
    with pytest.raises(ValueError):
        g.add_task("a", lambda: 2)


def test_add_task_duplicate_dep():
    g = TaskGraph()
    g.add_task("x", lambda: 0)
    with pytest.raises(ValueError):
        g.add_task("y", lambda **kw: 0, deps=["x", "x"])


def test_add_task_error_leaves_graph_unchanged():
    g = TaskGraph()
    g.add_task("a", lambda: 1)
    with pytest.raises(ValueError):
        g.add_task("a", lambda: 2)
    assert g.topological_order() == ["a"]


# ---------- Validation ----------

def test_missing_dependency():
    g = TaskGraph()
    g.add_task("a", lambda: 1)
    g.add_task("b", lambda **kw: kw["z"], deps=["z"])
    with pytest.raises(MissingDependencyError) as exc_info:
        g.topological_order()
    assert exc_info.value.task == "b"
    assert exc_info.value.dependency == "z"


def test_self_cycle():
    g = TaskGraph()
    g.add_task("a", lambda **kw: 0, deps=["a"])
    with pytest.raises(CycleError) as exc_info:
        g.topological_order()
    assert exc_info.value.cycle == ["a", "a"]


def test_cycle_two_nodes():
    g = TaskGraph()
    g.add_task("a", lambda **kw: 0, deps=["b"])
    g.add_task("b", lambda **kw: 0, deps=["a"])
    with pytest.raises(CycleError) as exc_info:
        g.topological_order()
    cyc = exc_info.value.cycle
    assert cyc[0] == cyc[-1]
    assert cyc[0] == "a"
    assert cyc[1] == "b"


def test_cycle_three_nodes():
    g = TaskGraph()
    g.add_task("a", lambda **kw: 0, deps=["b"])
    g.add_task("b", lambda **kw: 0, deps=["c"])
    g.add_task("c", lambda **kw: 0, deps=["a"])
    with pytest.raises(CycleError) as exc_info:
        g.topological_order()
    cyc = exc_info.value.cycle
    assert cyc[0] == cyc[-1]
    assert len(cyc) == 4  # a, b, c, a


def test_missing_dep_checked_before_cycle():
    g = TaskGraph()
    g.add_task("a", lambda **kw: 0, deps=["b"])
    g.add_task("b", lambda **kw: 0, deps=["a"])  # cycle
    g.add_task("c", lambda **kw: 0, deps=["missing"])  # missing
    # "a" is checked first (insertion order), its dep "b" exists -> ok
    # "b" checked next, its dep "a" exists -> ok
    # "c" checked next, its dep "missing" -> MissingDependencyError
    with pytest.raises(MissingDependencyError):
        g.topological_order()


# ---------- Run basics ----------

def test_run_simple():
    g = TaskGraph()
    g.add_task("a", lambda: 1)
    g.add_task("b", lambda **kw: kw["a"] + 10, deps=["a"])
    g.add_task("c", lambda **kw: kw["b"] * 2, deps=["b"])
    res = g.run(max_workers=2)
    assert res.results == {"a": 1, "b": 11, "c": 22}
    assert res.errors == {}
    assert res.skipped == set()
    assert set(res.order) == {"a", "b", "c"}


def test_run_serial_order():
    g = TaskGraph()
    g.add_task("x", lambda: 1)
    g.add_task("y", lambda **kw: kw["x"], deps=["x"])
    g.add_task("z", lambda: 2)
    res = g.run(max_workers=1)
    # max_workers=1 serial: order must match topological_order
    topo = g.topological_order()
    assert res.order == topo


def test_run_failure_propagates_skip():
    g = TaskGraph()
    g.add_task("a", lambda: (_ for _ in ()).throw(RuntimeError("boom")))
    g.add_task("b", lambda **kw: kw["a"], deps=["a"])
    g.add_task("c", lambda **kw: kw["b"], deps=["b"])
    g.add_task("d", lambda: 99)  # independent
    res = g.run(max_workers=2)
    assert "a" in res.errors
    assert isinstance(res.errors["a"], RuntimeError)
